def list_dashboards(collection_id=None, status=None, archived=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_dashboards"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now()
        })
        _save("request_logs.json", logs)

    def _parse_cursor(c):
        if c is None:
            return None
        if not isinstance(c, str) or not c:
            return None
        try:
            raw = base64.urlsafe_b64decode(c.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if obj.get("endpoint") != endpoint:
                return None
            v = obj.get("v")
            if v != 1:
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        payload = {"endpoint": endpoint, "v": 1, "offset": off}
        raw = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Input validation
    try:
        if collection_id is not None:
            if not isinstance(collection_id, str) or re.match(r"^mbc_[0-9A-Z]{18,}$", collection_id) is None:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "collection_id is malformed.")
        if status is not None:
            if status not in ("active", "archived", "deleted"):
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "status must be one of: active, archived, deleted.")
        if archived is not None and not isinstance(archived, bool):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "archived must be a boolean.")
        if limit is None:
            limit = 50
        if not isinstance(limit, int) or limit < 1 or limit > 200:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
        if sort is None:
            sort = "updated_at"
        if sort not in ("created_at", "updated_at", "name"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort must be one of: created_at, updated_at, name.")
        if order is None:
            order = "desc"
        if order not in ("asc", "desc"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order must be one of: asc, desc.")

        offset = 0
        if cursor is not None:
            offset = _parse_cursor(cursor)
            if offset is None:
                _log("VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "cursor is invalid or expired.")
    except Exception:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid request.")

    # Ambient auth: if store contains nothing usable at all, treat as unauthorized.
    dashboards = _load("metabase_dashboards.json")
    if not isinstance(dashboards, list):
        dashboards = []
    if len(dashboards) == 0:
        _log("UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No authorized context available to list dashboards.")

    # Apply business rule: list excludes deleted
    rows = [d for d in dashboards if isinstance(d, dict) and d.get("status") != "deleted"]

    # Filters
    if collection_id is not None:
        rows = [d for d in rows if d.get("collection_id") == collection_id]
    if status is not None:
        if status == "deleted":
            # list_dashboards never includes deleted per business rule -> empty
            rows = []
        else:
            rows = [d for d in rows if d.get("status") == status]
    if archived is not None:
        rows = [d for d in rows if d.get("archived") is archived]

    # Sort
    def _key(d):
        v = d.get(sort)
        if v is None:
            return ""
        return v
    reverse = (order == "desc")
    try:
        rows.sort(key=_key, reverse=reverse)
    except Exception:
        # If sorting fails due to mixed types, fall back to string representation deterministically.
        rows.sort(key=lambda d: str(d.get(sort, "")), reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }
    _log("OK")
    return resp

