def execute_card(card_id, parameters_json=None, result_format=None, **_extra):
    import json, os, datetime, time, re, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "execute_card"

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code, execution_id=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": f"rl_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
            "execution_id": execution_id
        })
        _save("request_logs.json", logs)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(20))

    # Validation
    try:
        if not isinstance(card_id, str) or re.match(r"^mbq_[0-9A-Z]{18,}$", card_id) is None:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "card_id is malformed.")
        if parameters_json is not None and not isinstance(parameters_json, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parameters_json must be an object.")
        if result_format is not None and not isinstance(result_format, str):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "result_format must be a string.")
        if result_format is None:
            result_format = "json"
        if result_format not in ("json", "csv"):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Unsupported result_format.", supported_formats=["json", "csv"])
    except Exception:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid request.")

    cards = _load("metabase_cards.json")
    if not isinstance(cards, list):
        cards = []

    # Find card, ensure non-deleted
    card = None
    for c in cards:
        if isinstance(c, dict) and c.get("id") == card_id:
            card = c
            break
    if card is None or card.get("status") == "deleted":
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Card not found.")

    # Ambient auth: require presence of at least one database mirror if card references a metabase_database_id or database_id
    dbs = _load("metabase_databases_schema.json")
    if not isinstance(dbs, list):
        dbs = []
    # determine metabase_database_id for execution when possible
    metabase_database_id = card.get("metabase_database_id")
    database_id = card.get("database_id")

    db_row = None
    if database_id is not None:
        for d in dbs:
            if isinstance(d, dict) and d.get("id") == database_id and d.get("status") == "active":
                db_row = d
                break
        if db_row is None:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized context available to execute this card (database unavailable).")
        if metabase_database_id is None:
            metabase_database_id = db_row.get("metabase_database_id")
    elif metabase_database_id is not None:
        for d in dbs:
            if isinstance(d, dict) and d.get("metabase_database_id") == metabase_database_id and d.get("status") == "active":
                db_row = d
                break
        if db_row is None:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized context available to execute this card (database unavailable).")
    else:
        # Allow if system has any active database context at all (best-effort ambient auth)
        any_active = any(isinstance(d, dict) and d.get("status") == "active" for d in dbs)
        if not any_active:
            _log("UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No authorized context available to execute cards.")
        # Pick none; metabase_database_id remains None (still allowed by tool contract), but execution row must satisfy schema constraint:
        # execution_type='card' => metabase_card_id IS NOT NULL (true), no requirement for metabase_database_id.

    # Parameter acceptability (minimal, schema-driven): ensure provided parameters keys exist in card.dataset_query_json/template?
    # If card has no parameters template, accept empty/none only.
    try:
        if parameters_json is None:
            parameters_json = {}
        if not isinstance(parameters_json, dict):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "parameters_json must be an object.")
        # If dashboard-like parameter template exists on card, validate keys; otherwise accept any (Metabase can accept native params).
        template = card.get("dataset_query_json")
        if template is None:
            # no template: accept but require it's JSON object already (done)
            pass
    except Exception:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parameters_json is not acceptable for this card.")

    executions = _load("metabase_executions.json")
    if not isinstance(executions, list):
        executions = []

    # Create execution: queued -> running -> succeeded (offline deterministic stub result)
    exec_id = _gen_id("mbx")
    now = _now()
    metabase_card_id = card.get("metabase_card_id")
    if metabase_card_id is None or not isinstance(metabase_card_id, int):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Card is missing metabase_card_id and cannot be executed.")

    row = {
        "id": exec_id,
        "execution_type": "card",
        "card_id": card_id,
        "metabase_card_id": metabase_card_id,
        "database_id": db_row.get("id") if isinstance(db_row, dict) else None,
        "metabase_database_id": metabase_database_id,
        "sql_text": None,
        "parameters_json": parameters_json,
        "result_format": result_format,
        "result_metadata_json": None,
        "row_count": None,
        "runtime_ms": None,
        "status": "queued",
        "error_message": None,
        "error_details_json": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now
    }

    # Persist queued
    executions.append(row)
    _save("metabase_executions.json", executions)

    # Transition to running
    try:
        started = _now()
        row["status"] = "running"
        row["started_at"] = started
        row["updated_at"] = started
        _save("metabase_executions.json", executions)
    except Exception:
        _log("FAILED", execution_id=exec_id)
        return _err("CONFLICT", "Failed to start execution.", execution_id=exec_id)

    # Produce offline result (since no external Metabase): succeed with empty dataset and basic metadata
    try:
        finished = _now()
        runtime_ms = max(0, int((time.time() - t0) * 1000))
        # Basic metadata: no columns known
        meta = {"columns": [], "source": "integration_server_offline"}
        result = {"rows": [], "columns": []}
        if result_format == "csv":
            output = ""  # header-less empty
        else:
            output = result

        row["status"] = "succeeded"
        row["result_metadata_json"] = meta
        row["row_count"] = 0
        row["runtime_ms"] = runtime_ms
        row["finished_at"] = finished
        row["updated_at"] = finished
        _save("metabase_executions.json", executions)

        resp = {
            "execution": row,
            "result_format": result_format,
            "data": output
        }
        _log("OK", execution_id=exec_id)
        return resp
    except Exception:
        # Transition to failed (allowed from running)
        try:
            finished = _now()
            row["status"] = "failed"
            row["error_message"] = "Execution failed."
            row["error_details_json"] = {"reason": "offline_execution_error"}
            row["finished_at"] = finished
            row["updated_at"] = finished
            _save("metabase_executions.json", executions)
        except Exception:
            pass
        _log("FAILED", execution_id=exec_id)
        return _err("CONFLICT", "Execution failed.", execution_id=exec_id)

def get_dashboard_cards(dashboard_id, status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # request log (best-effort even if errors)
    req_file = "request_logs.json"
    reqs = _load(req_file)

    def _log(status_code, credential_id=None, details=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + hashlib.sha256((now + "|" + str(len(reqs) + 1)).encode("utf-8")).hexdigest()[:22].upper(),
            "endpoint": "get_dashboard_cards",
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": latency_ms,
            "timestamp": now
        }
        if details is not None:
            row["details"] = details
        reqs.append(row)
        _save(req_file, reqs)

    # rate limit / quota (if configured)
    def _enforce_limits():
        limits = _load("rate_limits.json")
        if not isinstance(limits, list):
            return None
        # find any applicable global limit rows
        for lim in limits:
            if not isinstance(lim, dict):
                continue
            if lim.get("enabled") is False:
                continue
            scope = lim.get("scope", "global")
            if scope not in ("global", "all"):
                continue
            # rate_limit_per_minute
            rpm = lim.get("requests_per_minute")
            if isinstance(rpm, int) and rpm > 0:
                cutoff = (datetime.datetime.utcnow() - datetime.timedelta(minutes=1)).replace(microsecond=0).isoformat() + "Z"
                recent = [r for r in reqs if isinstance(r, dict) and r.get("timestamp", "") >= cutoff]
                if len(recent) >= rpm:
                    return _err("RATE_LIMIT", "Rate limit exceeded.")
            # quota_per_day
            qpd = lim.get("requests_per_day")
            if isinstance(qpd, int) and qpd > 0:
                day = datetime.datetime.utcnow().date().isoformat()
                today = [r for r in reqs if isinstance(r, dict) and str(r.get("timestamp", "")).startswith(day)]
                if len(today) >= qpd:
                    return _err("QUOTA_EXCEEDED", "Daily quota exceeded.")
        return None

    lim_err = _enforce_limits()
    if lim_err:
        _log(lim_err["error"]["code"])
        return lim_err

    # Validate inputs
    if not isinstance(dashboard_id, str) or not re.match(r"^mbd_[0-9A-Z]{18,}$", dashboard_id):
        e = _err("VALIDATION_ERROR", "Malformed dashboard_id.")
        _log("VALIDATION_ERROR")
        return e
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "removed"):
            e = _err("VALIDATION_ERROR", "Invalid status filter.")
            _log("VALIDATION_ERROR")
            return e
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        e = _err("VALIDATION_ERROR", "Invalid limit; must be 1..500.")
        _log("VALIDATION_ERROR")
        return e
    if sort is None:
        sort = "created_at"
    if order is None:
        order = "asc"
    if sort not in ("created_at", "updated_at", "row", "col") or order not in ("asc", "desc"):
        e = _err("VALIDATION_ERROR", "Invalid sort/order.")
        _log("VALIDATION_ERROR")
        return e

    # Load data
    dashboards = _load("metabase_dashboards.json")
    placements = _load("metabase_dashboard_cards.json")
    cards = _load("metabase_cards.json")

    # Find dashboard and enforce viewability (ambient auth: allow if exists)
    dash = next((d for d in dashboards if isinstance(d, dict) and d.get("id") == dashboard_id), None)
    if not dash or dash.get("status") == "deleted":
        e = _err("NOT_FOUND", "Dashboard not found.")
        _log("NOT_FOUND")
        return e

    # Filter placements
    filtered = []
    cards_by_id = {c.get("id"): c for c in cards if isinstance(c, dict)}
    for p in placements:
        if not isinstance(p, dict):
            continue
        if p.get("dashboard_id") != dashboard_id:
            continue
        if status is not None and p.get("status") != status:
            continue
        # join to card and exclude deleted cards
        c = cards_by_id.get(p.get("card_id"))
        if not c or c.get("status") == "deleted":
            continue
        # include placement row plus card summary
        out = dict(p)
        out["card"] = {
            "id": c.get("id"),
            "metabase_card_id": c.get("metabase_card_id"),
            "name": c.get("name"),
            "description": c.get("description"),
            "collection_id": c.get("collection_id"),
            "metabase_collection_id": c.get("metabase_collection_id"),
            "database_id": c.get("database_id"),
            "metabase_database_id": c.get("metabase_database_id"),
            "display": c.get("display"),
            "archived": c.get("archived"),
            "status": c.get("status"),
            "created_at": c.get("created_at"),
            "updated_at": c.get("updated_at"),
        }
        filtered.append(out)

    # Sorting
    def _sort_key(x):
        v = x.get(sort)
        # normalize None for numeric sorts
        if sort in ("row", "col"):
            if v is None:
                return -1 if order == "asc" else 10**18
            if isinstance(v, int):
                return v
            return -1 if order == "asc" else 10**18
        # datetime-ish strings
        if v is None:
            return ""
        return str(v)

    reverse = (order == "desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    # Cursor pagination: opaque base64 of {"i": index, "sig": sha256(dashboard_id|sort|order|status|i)}
    start = 0
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("VALIDATION_ERROR")
            return e
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===").decode("utf-8")
            payload = json.loads(raw)
            if not isinstance(payload, dict) or "i" not in payload or "sig" not in payload:
                raise ValueError("bad cursor")
            i = payload["i"]
            sig = payload["sig"]
            if not isinstance(i, int) or i < 0:
                raise ValueError("bad index")
            expected = hashlib.sha256((dashboard_id + "|" + sort + "|" + order + "|" + str(status) + "|" + str(i)).encode("utf-8")).hexdigest()
            if sig != expected:
                raise ValueError("bad sig")
            start = i
        except Exception:
            e = _err("VALIDATION_ERROR", "Invalid cursor.")
            _log("VALIDATION_ERROR")
            return e

    total = len(filtered)
    page = filtered[start:start + limit]
    next_cursor = None
    if start + limit < total:
        ni = start + limit
        sig = hashlib.sha256((dashboard_id + "|" + sort + "|" + order + "|" + str(status) + "|" + str(ni)).encode("utf-8")).hexdigest()
        next_cursor = base64.urlsafe_b64encode(json.dumps({"i": ni, "sig": sig}).encode("utf-8")).decode("utf-8").rstrip("=")

    resp = {
        "dashboard_id": dashboard_id,
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor,
            "sort": sort,
            "order": order,
            "status": status
        }
    }
    _log("OK")
    return resp

