def create_dashboard(name, description=None, collection_id=None, parameters_json=None, archived=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_files = ["request_logs.json", "requests.json", "usage.json", "audit_log.json", "audit_logs.json"]
    usage_file = None
    for fn in usage_files:
        if os.path.exists(os.path.join(_DB, fn)):
            usage_file = fn
            break

    def _log(status, credential=None, error_code=None):
        if not usage_file:
            return
        logs = _load(usage_file)
        entry = {
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("="),
            "endpoint": "create_dashboard",
            "timestamp": now,
            "status": status,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if credential is not None:
            entry["credential"] = credential
        if error_code is not None:
            entry["error_code"] = error_code
        if isinstance(logs, list):
            logs.append(entry)
            _save(usage_file, logs)

    if not isinstance(name, str) or name.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^mbc_[0-9A-Z]{18,}$", collection_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Malformed collection_id.")
    if parameters_json is not None and not isinstance(parameters_json, dict):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parameters_json must be an object.")
    if archived is not None and not isinstance(archived, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "archived must be a boolean.")

    collections = _load("metabase_collections.json")
    if collection_id is not None:
        colrow = next((c for c in collections if c.get("id") == collection_id), None)
        if not colrow or colrow.get("status") == "deleted":
            _log("error", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found.")
        metabase_collection_id = colrow.get("metabase_collection_id")
    else:
        colrow = None
        metabase_collection_id = None

    dashboards = _load("metabase_dashboards.json")

    # create unique metabase_dashboard_id (simulating Metabase response id assignment)
    used = {d.get("metabase_dashboard_id") for d in dashboards if isinstance(d.get("metabase_dashboard_id"), int)}
    metabase_dashboard_id = 1
    while metabase_dashboard_id in used:
        metabase_dashboard_id += 1

    # local id convention: mbd_
    new_id = "mbd_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    is_archived = bool(archived) if archived is not None else False
    status = "archived" if is_archived else "active"

    row = {
        "id": new_id,
        "metabase_dashboard_id": metabase_dashboard_id,
        "name": name.strip(),
        "description": description,
        "collection_id": collection_id,
        "metabase_collection_id": metabase_collection_id,
        "parameters_json": parameters_json,
        "archived": is_archived,
        "status": status,
        "created_at": now,
        "updated_at": now,
    }

    # Constraint: archived = (status='archived') OR status in ('active','deleted') is satisfied.
    # Constraint: collection mapping consistency if both set is satisfied by our assignment.

    dashboards.append(row)
    _save("metabase_dashboards.json", dashboards)
    _log("ok")
    return {"data": row}

