    if status is not None and status not in ("active", "archived", "deleted"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.")
    if parent_metabase_collection_id is not None and not isinstance(parent_metabase_collection_id, int):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_metabase_collection_id must be an integer.")
    if limit is not None:
        if not isinstance(limit, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer.")
        if limit < 1 or limit > 200:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200.")
    if sort is not None and sort not in ("created_at", "updated_at", "name"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid sort field.")
    if order is not None and order not in ("asc", "desc"):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order.")
    if cursor is not None and not isinstance(cursor, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.")

    # default server behavior if omitted
    if limit is None:
        limit = 50
    if sort is None:
        sort = "updated_at"
    if order is None:
        order = "desc"

    start = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            if isinstance(payload, dict) and payload.get("o") == "collections" and isinstance(payload.get("s"), int) and payload.get("s") >= 0:
                start = payload["s"]
            else:
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        except Exception:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor.")

    rows = _load("metabase_collections.json")
    # Business rule: list_collections returns status != 'deleted' unless explicitly filtered
    if status is None:
        rows = [r for r in rows if r.get("status") != "deleted"]
    else:
        rows = [r for r in rows if r.get("status") == status]

    if parent_metabase_collection_id is not None:
        rows = [r for r in rows if r.get("parent_metabase_collection_id") == parent_metabase_collection_id]

    total = len(rows)

    reverse = (order == "desc")

    def _sort_key(r):
        v = r.get(sort)
        if sort in ("created_at", "updated_at"):
            if not isinstance(v, str):
                v = ""
            return v
        if sort == "name":
            return (v or "").lower()
        return v

    rows.sort(key=_sort_key, reverse=reverse)

    page = rows[start:start + limit]
    next_start = start + len(page)
    has_more = next_start < total
    next_cursor = None
    if has_more:
        payload = {"o": "collections", "s": next_start}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    _log("ok")
    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort": sort,
            "order": order,
        },
    }

def create_collection(name, description=None, parent_metabase_collection_id=None, color=None, authority_level=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    usage_files = ["request_logs.json", "requests.json", "usage.json", "audit_log.json", "audit_logs.json"]
    usage_file = None
    for fn in usage_files:
        if os.path.exists(os.path.join(_DB, fn)):
            usage_file = fn
            break

    def _log(status_s, credential=None, error_code=None):
        if not usage_file:
            return
        logs = _load(usage_file)
        entry = {
            "id": "req_" + base64.b32encode(os.urandom(10)).decode("ascii").rstrip("="),
            "endpoint": "create_collection",
            "timestamp": now,
            "status": status_s,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if credential is not None:
            entry["credential"] = credential
        if error_code is not None:
            entry["error_code"] = error_code
        if isinstance(logs, list):
            logs.append(entry)
            _save(usage_file, logs)

    if not isinstance(name, str) or name.strip() == "":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name is required and must be a non-empty string.")
    if description is not None and not isinstance(description, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string.")
    if parent_metabase_collection_id is not None and not isinstance(parent_metabase_collection_id, int):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_metabase_collection_id must be an integer.")
    if color is not None and not isinstance(color, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "color must be a string.")
    if authority_level is not None and not isinstance(authority_level, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "authority_level must be a string.")

    collections = _load("metabase_collections.json")

    # parent_metabase_collection_id != metabase_collection_id will be validated after we assign new metabase_collection_id.
    # Simulate Metabase assigning a new metabase_collection_id (source of truth).
    used = {c.get("metabase_collection_id") for c in collections if isinstance(c.get("metabase_collection_id"), int)}
    metabase_collection_id = 1
    while metabase_collection_id in used:
        metabase_collection_id += 1

    if parent_metabase_collection_id is not None and parent_metabase_collection_id == metabase_collection_id:
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_metabase_collection_id cannot equal metabase_collection_id.")

    new_id = "mbc_" + base64.b32encode(os.urandom(12)).decode("ascii").rstrip("=")

    row = {
        "id": new_id,
        "metabase_collection_id": metabase_collection_id,
        "name": name.strip(),
        "description": description,
        "parent_metabase_collection_id": parent_metabase_collection_id,
        "location_path": None,
        "color": color,
        "authority_level": authority_level,
        "status": "active",
        "created_at": now,
        "updated_at": now,
    }

    # Unique(metabase_collection_id) ensured by generation above
    collections.append(row)
    _save("metabase_collections.json", collections)
    _log("ok")
    return {"data": row}

def list_tables(database_id=None, metabase_database_id=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "list_tables",
            "credential_id": None,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
        }
        if isinstance(extra, dict) and extra:
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _validate_cursor(cur):
        # Accept vendor "opaque cursor" as either our base64 cursor or legacy/plain string (treated as offset 0)
        if cur is None:
            return (0, None)
        if not isinstance(cur, str) or cur == "":
            return (None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided"))
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if isinstance(obj, dict) and obj.get("v") == 1 and isinstance(obj.get("offset"), int) and obj["offset"] >= 0:
                return (obj["offset"], None)
        except Exception:
            pass
        # If it's not our cursor format, treat as a valid opaque cursor that maps to offset 0
        return (0, None)

    def _make_cursor(offset):
        payload = {"v": 1, "offset": offset}
        raw = json.dumps(payload, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # Validate limit
    if limit is None:
        limit_i = 50
    else:
        if not isinstance(limit, int):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit < 1 or limit > 200:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
        limit_i = limit

    # Validate identifiers (relaxed: allow both; prefer database_id when present, else metabase_database_id)
    dbid = None
    mbid = None
    if database_id is not None:
        if not isinstance(database_id, str) or not re.match(r"^mbdb_[0-9A-Z]{18,}$", database_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "database_id is malformed")
        dbid = database_id
    if metabase_database_id is not None:
        if not isinstance(metabase_database_id, int):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "metabase_database_id must be an integer")
        mbid = metabase_database_id
    if dbid is None and mbid is None:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide at least one of database_id or metabase_database_id")

    offset, cerr = _validate_cursor(cursor)
    if cerr:
        _log("error", "VALIDATION_ERROR")
        return cerr

    # Load database mirror rows
    dbs = _load("metabase_databases_schema.json")
    if not isinstance(dbs, list):
        dbs = []

    # Resolve database row: prefer explicit database_id match; else metabase id match; if both provided and conflict -> CONFLICT
    db_row = None
    if dbid is not None:
        for r in dbs:
            if isinstance(r, dict) and r.get("id") == dbid:
                db_row = r
                break
        if db_row is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Database not found", database_id=dbid)
        if db_row.get("status") != "active":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Database not active", database_id=dbid)
        if mbid is not None and isinstance(db_row.get("metabase_database_id"), int) and db_row.get("metabase_database_id") != mbid:
            _log("error", "CONFLICT")
            return _err("CONFLICT", "database_id and metabase_database_id refer to different databases",
                        database_id=dbid, metabase_database_id=mbid)
    else:
        for r in dbs:
            if isinstance(r, dict) and r.get("metabase_database_id") == mbid and r.get("status") == "active":
                db_row = r
                break
        if db_row is None:
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Database not found", metabase_database_id=mbid)

    tables = db_row.get("tables")
    if not isinstance(tables, list):
        tables = []

    # Stable sort for pagination
    def _tkey(t):
        if not isinstance(t, dict):
            return ("", -1)
        name = t.get("name")
        if not isinstance(name, str):
            name = ""
        tid = t.get("metabase_table_id")
        if not isinstance(tid, int):
            tid = -1
        return (name.lower(), tid)

    tables_sorted = [t for t in tables if isinstance(t, dict)]
    tables_sorted.sort(key=_tkey)

    total = len(tables_sorted)
    page = tables_sorted[offset: offset + limit_i]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    resp = {
        "database": {
            "id": db_row.get("id"),
            "metabase_database_id": db_row.get("metabase_database_id"),
            "name": db_row.get("name"),
            "engine": db_row.get("engine"),
        },
        "tables": [
            {
                "metabase_table_id": t.get("metabase_table_id"),
                "name": t.get("name"),
                "schema": t.get("schema"),
                "description": t.get("description"),
            }
            for t in page
        ],
        "pagination": {
            "limit": limit_i,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "total": total,
            "has_more": has_more,
        },
    }
    _log("ok")
    return resp

def get_table_fields(database_id=None, metabase_database_id=None, table_name=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    _now = _now_dt.isoformat() + "Z"

    # ---------------- logs / rate limit (best-effort if request_logs.json exists) ----------------
    def _load_logs():
        logs = _load("request_logs.json")
        return logs if isinstance(logs, list) else []

    def _parse_ts(x):
        if not isinstance(x, str):
            return None
        s = x.strip()
        if s.endswith("Z"):
            s = s[:-1]
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _write_log(status, error_code=None, extra=None):
        try:
            logs = _load_logs()
            row = {
                "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": "get_table_fields",
                "credential_id": None,
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - _t0) * 1000),
                "timestamp": _now,
            }
            if isinstance(extra, dict):
                row.update(extra)
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            # Never fail the API call because logging failed
            return

    def _enforce_rate_limit():
        try:
            logs = _load_logs()
            window_s = 60
            limit_per_window = 60
            cutoff = _now_dt - datetime.timedelta(seconds=window_s)
            recent = 0
            for r in logs:
                if not isinstance(r, dict):
                    continue
                if r.get("endpoint") != "get_table_fields":
                    continue
                ts = _parse_ts(r.get("timestamp"))
                if ts is None:
                    continue
                if ts >= cutoff:
                    recent += 1
            if recent >= limit_per_window:
                return _err("RATE_LIMIT", "Rate limit exceeded", window_seconds=window_s, limit=limit_per_window)
            return None
        except Exception:
            return None

    rl = _enforce_rate_limit()
    if isinstance(rl, dict) and rl.get("error"):
        _write_log("error", rl["error"].get("code"))
        return rl

    # ---------------- validation ----------------
    if not isinstance(table_name, str) or not table_name.strip():
        e = _err("VALIDATION_ERROR", "table_name is required and must be a non-empty string", table_name=table_name)
        _write_log("error", e["error"]["code"])
        return e
    table_name_norm = table_name.strip()

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer", limit=limit)
        _write_log("error", e["error"]["code"])
        return e
    if limit < 1 or limit > 500:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 500", limit=limit)
        _write_log("error", e["error"]["code"])
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string when provided", cursor=cursor)
        _write_log("error", e["error"]["code"])
        return e

    if database_id is not None:
        if not isinstance(database_id, str):
            e = _err("VALIDATION_ERROR", "database_id must be a string when provided", database_id=database_id)
            _write_log("error", e["error"]["code"])
            return e
        # Relaxed validation: accept valid ids but do not reject unknown formats too aggressively
        if not re.match(r"^mbdb_[0-9A-Z]{18,}$", database_id):
            e = _err("VALIDATION_ERROR", "database_id has an invalid format", database_id=database_id)
            _write_log("error", e["error"]["code"])
            return e

    if metabase_database_id is not None and not isinstance(metabase_database_id, int):
        e = _err("VALIDATION_ERROR", "metabase_database_id must be an integer when provided", metabase_database_id=metabase_database_id)
        _write_log("error", e["error"]["code"])
        return e

    if database_id is None and metabase_database_id is None:
        e = _err("VALIDATION_ERROR", "Either database_id or metabase_database_id must be provided")
        _write_log("error", e["error"]["code"])
        return e

    # ---------------- load databases schema mirror ----------------
    raw = _load("metabase_databases_schema.json")
    rows = raw.get("data") if isinstance(raw, dict) and isinstance(raw.get("data"), list) else (raw if isinstance(raw, list) else [])
    if not isinstance(rows, list):
        rows = []

    # Prefer active rows; if none match, fall back to any status for identifier matching then enforce NOT_FOUND/deleted
    def _matches_db(r):
        if not isinstance(r, dict):
            return False
        if database_id is not None and r.get("id") == database_id:
            return True
        if metabase_database_id is not None and r.get("metabase_database_id") == metabase_database_id:
            return True
        return False

    candidate_rows = [r for r in rows if _matches_db(r)]
    # If both identifiers supplied, try to find a row satisfying both; otherwise accept any match by the provided identifier
    chosen = None
    if database_id is not None and metabase_database_id is not None:
        for r in candidate_rows:
            if r.get("id") == database_id and r.get("metabase_database_id") == metabase_database_id:
                chosen = r
                break
        if chosen is None:
            # Ambiguous or inconsistent identifiers
            e = _err(
                "VALIDATION_ERROR",
                "database_id and metabase_database_id refer to different databases",
                database_id=database_id,
                metabase_database_id=metabase_database_id,
            )
            _write_log("error", e["error"]["code"])
            return e
    else:
        chosen = candidate_rows[0] if candidate_rows else None

    if chosen is None:
        e = _err(
            "NOT_FOUND",
            "Database schema mirror not found",
            database_id=database_id,
            metabase_database_id=metabase_database_id,
        )
        _write_log("error", e["error"]["code"])
        return e

    if chosen.get("status") != "active":
        e = _err(
            "NOT_FOUND",
            "Database schema mirror not found",
            database_id=chosen.get("id"),
            metabase_database_id=chosen.get("metabase_database_id"),
        )
        _write_log("error", e["error"]["code"])
        return e

    tables = chosen.get("tables")
    if not isinstance(tables, list):
        tables = []

    # ---------------- locate table ----------------
    # Primary: match by exact name; fallback: case-insensitive name match
    table = None
    for t in tables:
        if isinstance(t, dict) and t.get("name") == table_name_norm:
            table = t
            break
    if table is None:
        lname = table_name_norm.lower()
        for t in tables:
            if isinstance(t, dict) and isinstance(t.get("name"), str) and t.get("name").lower() == lname:
                table = t
                break

    if table is None:
        e = _err(
            "NOT_FOUND",
            "Table not found in database schema mirror",
            table_name=table_name_norm,
            database_id=chosen.get("id"),
            metabase_database_id=chosen.get("metabase_database_id"),
        )
        _write_log("error", e["error"]["code"])
        return e

    fields = table.get("fields")
    if not isinstance(fields, list):
        fields = []

    # Only active fields
    active_fields = [f for f in fields if isinstance(f, dict) and f.get("active") is True]

    # Stable ordering: by metabase_field_id then name
    def _field_key(f):
        mfi = f.get("metabase_field_id")
        try:
            mfi2 = int(mfi)
        except Exception:
            mfi2 = 10**18
        nm = f.get("name")
        return (mfi2, nm if isinstance(nm, str) else "")
    active_fields.sort(key=_field_key)

    # ---------------- pagination ----------------
    # Cursor is "offset:<int>" (opaque to caller; accept any string)
    offset = 0
    if isinstance(cursor, str) and cursor:
        if cursor.startswith("offset:"):
            try:
                offset = int(cursor.split(":", 1)[1])
                if offset < 0:
                    offset = 0
            except Exception:
                offset = 0
        else:
            # If cursor isn't recognized, treat as 0 (do not error; cursor is opaque)
            offset = 0

    total = len(active_fields)
    page = active_fields[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    resp = {
        "database": {
            "id": chosen.get("id"),
            "metabase_database_id": chosen.get("metabase_database_id"),
            "name": chosen.get("name"),
            "engine": chosen.get("engine"),
        },
        "table": {
            "metabase_table_id": table.get("metabase_table_id"),
            "name": table.get("name"),
            "schema": table.get("schema"),
            "description": table.get("description"),
        },
        "fields": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
    }

    _write_log("success", None, extra={"database_id": chosen.get("id"), "metabase_database_id": chosen.get("metabase_database_id")})
    return resp

def update_dashboard(dashboard_id, name=None, description=None, collection_id=None, parameters_json=None, archived=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    _now = _now_dt.isoformat() + "Z"

    def _log(status_s, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "update_dashboard",
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    # Validate dashboard_id
    if not isinstance(dashboard_id, str) or not re.match(r"^mbd_[0-9A-Z]{18,}$", dashboard_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "dashboard_id is malformed")

    # Validate optional fields types
    if name is not None and (not isinstance(name, str) or name.strip() == ""):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if description is not None and not isinstance(description, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string when provided")
    if collection_id is not None:
        if not isinstance(collection_id, str) or not re.match(r"^mbc_[0-9A-Z]{18,}$", collection_id):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "collection_id is malformed")
    if parameters_json is not None and not isinstance(parameters_json, dict):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parameters_json must be an object when provided")
    if archived is not None and not isinstance(archived, bool):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "archived must be a boolean when provided")
    allowed_status = {"active", "archived", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of active, archived, deleted")

    dashboards = _load("metabase_dashboards.json")
    if not isinstance(dashboards, list):
        dashboards = []

    idx = None
    for i, d in enumerate(dashboards):
        if isinstance(d, dict) and d.get("id") == dashboard_id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Dashboard not found")

    dash = dashboards[idx]
    cur_status = dash.get("status")
    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "deleted": set(),
    }
    if cur_status not in transitions:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Dashboard is in an unknown lifecycle state", current_status=cur_status)

    # If deleted, refuse any updates (including no-op)
    if cur_status == "deleted":
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot update a deleted dashboard", current_status=cur_status)

    # Resolve desired status considering archived flag
    desired_status = status
    if archived is not None:
        desired_status_from_archived = "archived" if archived else "active"
        if desired_status is not None and desired_status != desired_status_from_archived:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status conflicts with archived flag", status=status, archived=archived)
        desired_status = desired_status_from_archived

    # If collection_id provided, validate it exists and is not deleted; also enforce metabase_collection_id mapping constraint
    collections = _load("metabase_collections.json")
    if not isinstance(collections, list):
        collections = []
    coll_row = None
    if collection_id is not None:
        for c in collections:
            if isinstance(c, dict) and c.get("id") == collection_id:
                coll_row = c
                break
        if coll_row is None or coll_row.get("status") == "deleted":
            _log("error", "NOT_FOUND")
            return _err("NOT_FOUND", "Collection not found")
        # Enforce constraint: if both local collection_id and metabase_collection_id present, they must match
        if dash.get("metabase_collection_id") is not None and coll_row.get("metabase_collection_id") is not None:
            if dash.get("metabase_collection_id") != coll_row.get("metabase_collection_id"):
                _log("error", "CONFLICT")
                return _err("CONFLICT", "metabase_collection_id does not match referenced collection", metabase_collection_id=dash.get("metabase_collection_id"), collection_metabase_collection_id=coll_row.get("metabase_collection_id"))

    # Apply mutations (track if anything changes)
    changed = False

    if name is not None and name != dash.get("name"):
        dash["name"] = name
        changed = True
    if description is not None and description != dash.get("description"):
        dash["description"] = description
        changed = True
    if parameters_json is not None and parameters_json != dash.get("parameters_json"):
        dash["parameters_json"] = parameters_json
        changed = True
    if collection_id is not None and collection_id != dash.get("collection_id"):
        dash["collection_id"] = collection_id
        # Keep metabase_collection_id consistent if we have the collection row
        if coll_row is not None and coll_row.get("metabase_collection_id") is not None:
            dash["metabase_collection_id"] = coll_row.get("metabase_collection_id")
        changed = True

    # Lifecycle / archived handling
    if desired_status is not None and desired_status != cur_status:
        if desired_status not in transitions.get(cur_status, set()):
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Invalid dashboard status transition", from_status=cur_status, to_status=desired_status)
        dash["status"] = desired_status
        # Ensure archived flag consistent per constraint
        dash["archived"] = (desired_status == "archived")
        changed = True
    elif archived is not None:
        # archived change without status change (should not happen due to mapping above), but keep consistent anyway
        expected_status = "archived" if archived else "active"
        if expected_status != cur_status:
            if expected_status not in transitions.get(cur_status, set()):
                _log("error", "INVALID_TRANSITION")
                return _err("INVALID_TRANSITION", "Invalid dashboard status transition", from_status=cur_status, to_status=expected_status)
            dash["status"] = expected_status
            changed = True
        dash["archived"] = archived
        changed = True

    if not changed:
        # Realistic behavior: return current record without mutating timestamps
        _log("ok", None)
        return {"dashboard": dash, "updated": False}

    dash["updated_at"] = _now
    dashboards[idx] = dash
    _save("metabase_dashboards.json", dashboards)

    _log("ok", None)
    return {"dashboard": dash, "updated": True}

def delete_dashboard(dashboard_id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0534000" if __import__("os").path.isdir("./environment_mix/0534000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"rlog_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
            "endpoint": "delete_dashboard",
            "credential_id": None,
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - _t0) * 1000),
            "timestamp": _now,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    if not isinstance(dashboard_id, str) or not re.match(r"^mbd_[0-9A-Z]{18,}$", dashboard_id):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "dashboard_id is malformed")

    dashboards = _load("metabase_dashboards.json")
    if not isinstance(dashboards, list):
        dashboards = []

    idx = None
    for i, d in enumerate(dashboards):
        if isinstance(d, dict) and d.get("id") == dashboard_id:
            idx = i
            break
    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Dashboard not found")

    dash = dashboards[idx]
    cur_status = dash.get("status")

    transitions = {
        "active": {"archived", "deleted"},
        "archived": {"active", "deleted"},
        "deleted": set(),
    }
    if cur_status not in transitions:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Dashboard is in an unknown lifecycle state", current_status=cur_status)

    if cur_status == "deleted":
        # Mutation with no effect must not report success
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Dashboard already deleted")

    if "deleted" not in transitions[cur_status]:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Cannot transition dashboard to deleted", from_status=cur_status, to_status="deleted")

    # Soft delete dashboard
    dash["status"] = "deleted"
    dash["archived"] = False
    dash["updated_at"] = _now
    dashboards[idx] = dash
    _save("metabase_dashboards.json", dashboards)

    # Soft remove active placements
    placements = _load("metabase_dashboard_cards.json")
    if not isinstance(placements, list):
        placements = []
    changed_any = False
    for i, p in enumerate(placements):
        if not isinstance(p, dict):
            continue
        if p.get("dashboard_id") == dashboard_id and p.get("status") == "active":
            # transition active -> removed only
            p["status"] = "removed"
            p["updated_at"] = _now
            placements[i] = p
            changed_any = True
    if changed_any:
        _save("metabase_dashboard_cards.json", placements)

    _log("ok", None)
    return {"dashboard": dash, "removed_dashboard_cards_updated": changed_any}
